steps.script:
for c in tree.root.get_children():
	if c is AcceptDialog and c.visible:
		var stack = [c]
		while not stack.is_empty():
			var n = stack.pop_back()
			for ch in n.get_children():
				stack.append(ch)
				if ch is Button and str(ch.text) == "Decline":
					ch.pressed.emit()
					return true
return true

var d = tree.root.get_node("/root/AttackAssignmentDialog")
var b = d.get_node_or_null("Content/ButtonContainer/BackToSelectionButton")
if b == null:
	return "no back button"
return "%s|%s" % [str(b.text), str(b.visible)]

var base = "/root/Main/HUD_Right/VBoxContainer/FightScrollContainer/FightPanel/FightSelectionPanel/UnitList/"
var out = []
for uid in ["Fight_U_BOYZ_T", "Fight_U_WARBOSS_T"]:
	var b = tree.root.get_node_or_null(base + uid)
	if b == null:
		out.append(uid + ":missing")
	else:
		out.append(uid + (":enabled" if not b.disabled else ":disabled"))
return ", ".join(out)

var sel = tree.current_scene.fight_controller.unit_selector
var out = []
for i in range(sel.item_count):
	out.append(str(sel.get_item_text(i)))
return " / ".join(out)
